"""Game state machine (FR-5 pause/resume, FR-6 game over).

States: Playing, Paused, GameOver.

Transitions:
    start    -> Playing
    pause    -> Paused
    resume   -> Playing
    gameOver -> GameOver
    finish   -> done (return to menu / exit)   [resolves C14]
"""


class GameState:
    PLAYING = "Playing"
    PAUSED = "Paused"
    GAME_OVER = "GameOver"


class GameStateMachine:
    def __init__(self):
        self._state = None

    @property
    def state(self):
        return self._state

    def start(self):
        if self._state is None:
            self._state = GameState.PLAYING
        return self._state

    def pause(self):
        if self._state == GameState.PLAYING:
            self._state = GameState.PAUSED
        return self._state

    def resume(self):
        if self._state == GameState.PAUSED:
            self._state = GameState.PLAYING
        return self._state

    def game_over(self):
        if self._state in (GameState.PLAYING, GameState.PAUSED):
            self._state = GameState.GAME_OVER
        return self._state

    def finish(self):
        """GameOver -> done. Resolves the missing final state (C14)."""
        if self._state == GameState.GAME_OVER:
            self._state = None
        return self._state
