"""Game domain class: holds game state, score, and the question loop.

The question loop (FR-1, C15) iterates over the question list until every
question is answered, at which point the game moves to GameOver (FR-6).
"""

from spacefractions.game.state import GameState, GameStateMachine


class Game:
    def __init__(self, game_id, questions):
        self.id = game_id
        self.score = 0
        self.questions = list(questions)
        self._current = 0
        self._machine = GameStateMachine()
        self._machine.start()

    @property
    def state(self):
        return self._machine.state

    def play(self):
        return self._machine.start()

    def current_question(self):
        if self._current < len(self.questions):
            return self.questions[self._current]
        return None

    def progress(self):
        return self._current, len(self.questions)

    def submit_answer(self, answer_index):
        if self.state != GameState.PLAYING:
            raise RuntimeError("Game is not in progress")
        question = self.current_question()
        if question is None:
            self.game_over()
            return False
        correct = question.check_answer(answer_index)
        if correct:
            self.score += 1
        self._current += 1
        if self._current >= len(self.questions):
            self.game_over()
        return correct

    def pause(self):
        return self._machine.pause()

    def resume(self):
        return self._machine.resume()

    def game_over(self):
        return self._machine.game_over()

    def view_score(self):
        return self.score

    def is_finished(self):
        return self.state == GameState.GAME_OVER
