import json

from spacefractions.question.question import Question


def _encode_options(options):
    return json.dumps(list(options))


def _decode_options(raw):
    return json.loads(raw)


class QuestionRepository:
    def __init__(self, conn):
        self._conn = conn

    def all(self):
        cur = self._conn.execute(
            "SELECT id, prompt, options, correct_index FROM questions ORDER BY id"
        )
        return [self._row_to_question(row) for row in cur.fetchall()]

    def get(self, question_id):
        cur = self._conn.execute(
            "SELECT id, prompt, options, correct_index FROM questions WHERE id = ?",
            (question_id,),
        )
        row = cur.fetchone()
        return self._row_to_question(row) if row is not None else None

    def add(self, prompt, options, correct_index):
        cur = self._conn.execute(
            "INSERT INTO questions (prompt, options, correct_index) VALUES (?, ?, ?)",
            (prompt, _encode_options(options), correct_index),
        )
        self._conn.commit()
        return Question(cur.lastrowid, prompt, options, correct_index)

    def update(self, question):
        self._conn.execute(
            "UPDATE questions SET prompt = ?, options = ?, correct_index = ? WHERE id = ?",
            (question.prompt, _encode_options(question.options),
             question.correct_index, question.id),
        )
        self._conn.commit()

    def delete(self, question_id):
        self._conn.execute("DELETE FROM questions WHERE id = ?", (question_id,))
        self._conn.commit()

    def count(self):
        cur = self._conn.execute("SELECT COUNT(*) AS c FROM questions")
        return cur.fetchone()["c"]

    @staticmethod
    def _row_to_question(row):
        return Question(row["id"], row["prompt"],
                        _decode_options(row["options"]), row["correct_index"])
