"""UserService: authentication and authorization (ASR-2 security).

Passwords are stored as salted SHA-256 digests (standard library only),
never in plain text.
"""

import hashlib
import secrets

from spacefractions.user.user import User


class UserService:
    def __init__(self, conn):
        self._conn = conn

    def register(self, username, password):
        salt = secrets.token_hex(16)
        password_hash = self._hash(password, salt)
        cur = self._conn.execute(
            "INSERT INTO users (username, password_hash) VALUES (?, ?)",
            (username, password_hash),
        )
        self._conn.commit()
        return User(cur.lastrowid, username)

    def authenticate(self, username, password):
        cur = self._conn.execute(
            "SELECT id, username, password_hash FROM users WHERE username = ?",
            (username,),
        )
        row = cur.fetchone()
        if row is None:
            return None
        salt, expected = row["password_hash"].split(":", 1)
        if self._hash(password, salt) == expected:
            return User(row["id"], row["username"])
        return None

    @staticmethod
    def _hash(password, salt):
        digest = hashlib.sha256((salt + password).encode("utf-8")).hexdigest()
        return salt + ":" + digest
